1	export type Item = {
2	  type: string;
3	  material: string;
4	  enchantment: number;
5	  cursed: boolean;
6	};
7	
8	export type Step = {
9	  op: string;
10	  items: Item[];
11	};
12	
13	export type Scenario = {
14	  customer: { yearsWithMHPCO: number };
15	  steps: Step[];
16	};
17	
18	export type StepResult = {
19	  premium: number;
20	};
21	
22	export type ScenarioResult = {
23	  results: StepResult[];
24	};
25	
26	const BASE_PRICES: Record<string, number> = {
27	  sword: 100,
28	  amulet: 60,
29	  staff: 80,
30	  potion: 40,
31	  rune: 25,
32	  moonstone: 25,
33	};
34	
35	// Expressed as integer percent rather than a 1.1 factor: floating-point
36	// multiplication by 1.1 loses exactness (100 * 1.1 === 115.00000000000001),
37	// while scaling by 110 and dividing by 100 stays exact for these prices.
38	const FIRST_CONTRACT_PERCENT = 110;
39	const WHOLE_PERCENT = 100;
40	const CONTRACT_FEE = 5;
41	
42	const BLOCK_SIZE = 3;
43	const BLOCK_PRICE = 60;
44	
45	const COMPONENT_TYPES = ["rune", "moonstone"];
46	
47	const CURSED_PERCENT = 150;
48	
49	const basePriceOf = (item: Item): number =>
50	  item.cursed
51	    ? applyPercent(BASE_PRICES[item.type], CURSED_PERCENT)
52	    : BASE_PRICES[item.type];
53	
54	const applyPercent = (amount: number, percent: number): number =>
55	  (amount * percent) / WHOLE_PERCENT;
56	
57	const isComponent = (item: Item): boolean =>
58	  COMPONENT_TYPES.includes(item.type);
59	
60	const allAlike = (items: Item[]): boolean =>
61	  items.every((item) => item.type === items[0].type);
62	
63	// Only alike components combine into blocks — main items (swords, staves,
64	// potions, amulets) are always priced individually, however many there are.
65	const formsBuildingBlocks = (items: Item[]): boolean =>
66	  items.every(isComponent) && allAlike(items);
67	
68	const sumOfBasePrices = (items: Item[]): number =>
69	  items.reduce((total, item) => total + basePriceOf(item), 0);
70	
71	// Every group of BLOCK_SIZE alike components is priced as one discounted
72	// building block; leftovers keep their individual price.
73	const buildingBlockPriceOf = (items: Item[]): number => {
74	  const blocks = Math.floor(items.length / BLOCK_SIZE);
75	  const itemsInBlocks = blocks * BLOCK_SIZE;
76	  const leftovers = items.slice(itemsInBlocks);
77	  return blocks * BLOCK_PRICE + sumOfBasePrices(leftovers);
78	};
79	
80	const itemsPriceOf = (items: Item[]): number =>
81	  formsBuildingBlocks(items)
82	    ? buildingBlockPriceOf(items)
83	    : sumOfBasePrices(items);
84	
85	// Premiums are always rounded up — rounding in MHPCO's favour, per spec.
86	const premiumFor = (itemsPrice: number): number =>
87	  Math.ceil(applyPercent(itemsPrice, FIRST_CONTRACT_PERCENT) + CONTRACT_FEE);
88	
89	const quote = (step: Step): StepResult => ({
90	  premium: premiumFor(itemsPriceOf(step.items)),
91	});
92	
93	export const run = (scenario: Scenario): ScenarioResult => ({
94	  results: [quote(scenario.steps[0])],
95	});
